        Enumeration simpleNames = getSimpleChildrenNames();
        String childName = null;
        while (compositeNames.hasMoreElements()) {
            childName = (String) compositeNames.nextElement();
            check(childName, true, node);
        }
        while (simpleNames.hasMoreElements()) {
            childName = (String) simpleNames.nextElement();
            check(childName, false, node);
        }
