    /**This method sets the new simple element with the given tag name.
     * @param childName the tag name of the new element.
     * @exception DeploymentException is thrown if this is the tag name of the unbounded element or if it is not the tag name of the simple element or it is not the permitted name for the sub element of this composite element.
     * @return the created element of SimpleNusuthWebAppElement class type.
     */
    public SimpleNusuthWebAppElement setSimpleChild(String childName) throws DeploymentException {
        checkExistence(childName);
        if (isChildUnbounded(childName)) {
            throw new DeploymentException("Child named " + childName + " is unbounded, use add instead");
        }
        List sList = (List) simpleElements.get(childName);
        if (sList == null) {
            throw new DeploymentException("Child named " + childName + " is not simple");
        }
        Inclusion incl = (Inclusion) innerDTDTable.get(childName);
        List list = incl.getChoiceLinks();
        if (list != null) {
            Iterator iter = list.iterator();
            List tmpList;
            String linkName;
            while (iter.hasNext()) {
                linkName = (String) iter.next();
                tmpList = (List) simpleElements.get(linkName);
                if (tmpList == null) {
                    tmpList = (List) compositeElements.get(linkName);
                }
                tmpList.clear();
            }
        }
        SimpleNusuthWebAppElement res = new SimpleNusuthWebAppElement(childName, getDepth() + 1);
        sList.clear();
        sList.add(res);
        return res;
    }


