    public String compose(String doctype, String systemId) {
        StringBuffer sb = new StringBuffer();
        sb.append("<?xml version=\"1.0\" encoding=\"ISO-8859-1\"?>\r\n\r\n");
        sb.append("<!DOCTYPE " + doctype + " SYSTEM \"" + systemId + "\">\r\n\r\n");
        sb.append(toString());
        return sb.toString();
    }


    /**This method creates string from the composite element information. Needed for serialization.
     * When we wont to save the changed xml configuration of the web application in the xml file.
     * @return string which contains the formatted xml representation of this composite element.
     */
    public String toString() {
        StringBuffer sb = new StringBuffer();
        char[] tmp = null;
        if (getDepth() > 0) {
            tmp = new char[getDepth() * 2];
            Arrays.fill(tmp, ' ');
            sb.append(tmp);
        }
        sb.append("<" + getTag() + (getID() == null ? ">\r\n" : " id=\"" + getID() + "\">\r\n"));
        Object[] entries = innerDTDTable.entrySet().toArray();
        Arrays.sort(entries, new InclusionComparator());
        Enumeration children;
        for (int i = 0; i < entries.length; i++) {
            try {
                children = getSimpleChild((String) ((Map.Entry) entries[i]).getKey());
                while (children.hasMoreElements()) {
                    sb.append(children.nextElement().toString());
                }
            } catch (DeploymentException dex) {
            }
            try {
                children = getCompositeChild((String) ((Map.Entry) entries[i]).getKey());
                while (children.hasMoreElements()) {
                    sb.append(children.nextElement().toString());
                }
            } catch (DeploymentException dex) {
            }
        }
        /*    Enumeration en1 = getSimpleChildrenNames();
         Enumeration en2;
         while (en1.hasMoreElements()) {
         try {
         en2 = getSimpleChild((String)en1.nextElement());
         } catch(DeploymentException dex) {
         throw new IllegalStateException("Internal error occurs, nested: "+dex);
         }
         while (en2.hasMoreElements()) {
         sb.append(en2.nextElement().toString());
         }
         }
         en1 = getCompositeChildrenNames();
         while (en1.hasMoreElements()) {
         try {
         en2 = getCompositeChild((String)en1.nextElement());
         } catch(DeploymentException dex) {
         throw new IllegalStateException("Internal error occurs, nested: "+dex);
         }
         while (en2.hasMoreElements()) {
         sb.append(en2.nextElement().toString());
         }
         }*/
        if (getDepth() > 0) {
            sb.append(tmp);
        }
        sb.append("</" + getTag() + ">\r\n");
        return sb.toString();
    }


    /**This method sets the HashTable that contains the nesting information of the elements in the xml configuration file .
     * In this table any complex element name is associated with the set of names of it's sub elements.
     * @param newDTDTable this is the HashTable that contains the nesting information of the elements in the xml configuration file .
     */
    static void addDTDTable(String type, Hashtable newDTDTable) {
        dtdTables.put(type, newDTDTable);
    }


    /**This method checks if the given name is the tag name of the sub element of this composite element.
     * @param childName the tag name that this method should check.
     * @exception DeploymentException is thrown if the given name it is not the permitted name for the sub element of this composite element.
     */
    private void checkExistence(String childName) throws DeploymentException {
        if (innerDTDTable.get(childName) == null) {
            throw new DeploymentException("Child named " + childName + " not contained in dtd");
        }
    }


    /**This method is used to get the tag names from the choice list of this element
     * (if exists, the choice list includes the tag name this element).
     * If this element doesn't have the choice list then the empty Enumeration is returned.
     * @param the tag name of sub element.
     * @exception DeploymentException is thrown if the given name it is not the permitted name for the sub element of this composite element.
     * @return the enumeration of Strings - contains the tag names from the choice list.
     */
    public Enumeration getChildChoices(String childName) throws DeploymentException {
        checkExistence(childName);
        Inclusion incl = (Inclusion) innerDTDTable.get(childName);
        return incl.hasChoice() ? Collections.enumeration(incl.getChoiceLinks()) : new Enumeration() {
            public boolean hasMoreElements() {
                return false;
            }

            public Object nextElement() {
                return null;
            }
        };
    }

    public boolean equals(Object obj) {
        if (obj instanceof CompositeNusuthWebAppElement && super.equals(obj)) {
            try {
                CompositeNusuthWebAppElement other = (CompositeNusuthWebAppElement) obj;
                Enumeration names = other.getCompositeChildrenNames();
                while (names.hasMoreElements()) {
                    String name = (String) names.nextElement();
                    Enumeration enum = other.getCompositeChild(name);
                    List children = (List) compositeElements.get(name);
                    int count = 0;
                    while (enum.hasMoreElements()) {
                        CompositeNusuthWebAppElement composite = (CompositeNusuthWebAppElement) enum.nextElement();
                        if (!children.contains(composite)) {
                            return false;
                        }
                        count++;
                    }
                    if (count != children.size()) {
                        return false;
                    }
                }
                names = other.getSimpleChildrenNames();
                while (names.hasMoreElements()) {
                    String name = (String) names.nextElement();
                    Enumeration enum = other.getSimpleChild(name);
                    List children = (List) simpleElements.get(name);
                    int count = 0;
                    while (enum.hasMoreElements()) {
                        SimpleNusuthWebAppElement simple = (SimpleNusuthWebAppElement) enum.nextElement();
                        if (!children.contains(simple)) {
                            return false;
                        }
                        count++;
                    }
                    if (count != children.size()) {
                        return false;
                    }
                }
                return true;
            } catch (DeploymentException e) {
                return false;
            }
        }
        return false;
    }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.writeObject(type);
        out.writeObject(compose(type, ""));
    }

    private void readObject(ObjectInputStream in)
            throws IOException, ClassNotFoundException {
        String xmlType = (String) in.readObject();
        String xml = (String) in.readObject();
        CompositeNusuthWebAppElement conf
                = null;
        try {
            conf = NusuthAppConfigFactory.
                    createConfig(xmlType, new ByteArrayInputStream(xml.getBytes()));
        } catch (ParserException e) {
//e.printStackTrace();
            conf = null;
        }
        compositeElements = conf.compositeElements;
        dtdTable = conf.dtdTable;
        innerDTDTable = conf.innerDTDTable;
        simpleElements = conf.simpleElements;
        type = conf.type;
        depth = conf.depth;
        ID = conf.ID;
        node = conf.node;
        tag = conf.tag;
    }

    class InclusionComparator implements Comparator {

        public int compare(Object o1, Object o2) {
            if (!(o1 instanceof Map.Entry && o2 instanceof Map.Entry)) {
                return 0;
            }
            Inclusion inc1 = null;
            Inclusion inc2 = null;
            try {
                inc1 = (Inclusion) ((Map.Entry) o1).getValue();
                inc2 = (Inclusion) ((Map.Entry) o2).getValue();
            } catch (ClassCastException cce) {
                return 0;
            }
            return inc1.getOrder() - inc2.getOrder();
        }
    }
